mkdir -p /tmp/hdfsui-$$ && cat > /tmp/hdfsui-$$/ui.py <<'EOF'
import os, re, sys

root = sys.argv[1]
results = []
for dirpath, dirnames, filenames in os.walk(root):
    for fn in filenames:
        if not fn.endswith('.java'):
            continue
        p = os.path.join(dirpath, fn)
        try:
            src = open(p, encoding='utf-8', errors='replace').read()
        except Exception:
            continue
        lines = src.split('\n')
        imports = []
        for i, ln in enumerate(lines):
            m = re.match(r'\s*import\s+(static\s+)?([\w.]+)\s*;', ln)
            if m:
                fq = m.group(2)
                if fq.endswith('.*'):
                    continue
                simple = fq.split('.')[-1]
                imports.append((i, ln, fq, simple, bool(m.group(1))))
        if not imports:
            continue
        body_lines = [ln for i, ln in enumerate(lines) if not re.match(r'\s*import\s', ln)]
        body = '\n'.join(body_lines)
        code = re.sub(r'/\*.*?\*/', '', body, flags=re.S)
        code = re.sub(r'//[^\n]*', '', code)
        for (i, ln, fq, simple, isstatic) in imports:
            pat = re.compile(r'\b' + re.escape(simple) + r'\b')
            in_code = bool(pat.search(code))
            in_doc = bool(pat.search(body))
            if not in_doc:
                results.append((p, i+1, ln.strip(), 'UNUSED'))
            elif not in_code:
                results.append((p, i+1, ln.strip(), 'DOCONLY'))
for r in sorted(results):
    print('%s|%d|%s|%s' % r)
EOF
